<template>
  <div>
    <PageHeader v-if="!embedded" :title="$t('legacy.xd088a73e')" :description="$t('legacy.x1527536a')">
      <template #actions><PollingStatus :state="pollState" :updated-at="lastUpdated"/><el-button @click="openExclusions">{{ $t('legacy.x491edbaf') }}</el-button><el-switch v-model="autoRefresh" :active-text="$t('logViewer.autoRefresh')"/></template>
    </PageHeader>
    <div v-else class="embedded-header">
      <div><h3>{{ $t('legacy.xd088a73e') }}</h3><p>{{ $t('legacy.x1527536a') }}</p></div>
      <div class="embedded-actions"><PollingStatus :state="pollState" :updated-at="lastUpdated"/><el-button @click="openExclusions">{{ $t('legacy.x491edbaf') }}</el-button><el-switch v-model="autoRefresh" :active-text="$t('logViewer.autoRefresh')"/></div>
    </div>
    <el-row :gutter="12" class="stats"><el-col v-for="item in statItems" :key="item.key" :xs="12" :sm="8" :lg="4"><el-card shadow="never"><div class="stat-label">{{ item.label }}</div><div class="stat-value">{{ stats[item.key]||0 }}</div></el-card></el-col></el-row>
    <el-card shadow="never" class="filters"><div class="filter-bar"><el-form inline><el-form-item :label="$t('common.status')"><el-select v-model="status" clearable style="width:150px" @change="applyFilters"><el-option v-for="value in statuses" :key="value" :label="value" :value="value"/></el-select></el-form-item><el-form-item :label="$t('legacy.x13955e03')"><el-select v-model="campaignType" clearable style="width:140px" @change="applyFilters"><el-option :label="$t('legacy.xe099c261')" value="batch"/><el-option :label="$t('legacy.x2843e2f6')" value="realtime"/></el-select></el-form-item><el-form-item :label="$t('legacy.xb2db9f1c')"><el-select v-model="smppFilter" style="width:180px" @change="applyFilters"><el-option :label="$t('common.all')" :value="-1"/><el-option :label="$t('legacy.x18c63459')" :value="0"/><el-option v-for="cfg in smppConfigs" :key="cfg.id" :value="cfg.id" :label="`${cfg.name} (${cfg.host}:${cfg.port})`"/></el-select></el-form-item></el-form><el-button :loading="loading" @click="fetchData()"><el-icon><Refresh /></el-icon>{{ $t('common.refresh') }}</el-button></div></el-card>
    <div class="table-shell"><DataState :loading="loading" :has-data="items.length>0" :empty="!loading&&!error&&!items.length" :error="error" empty-:title="$t('legacy.xf388438a')" empty-:description="$t('legacy.xfb24ae8e')" @retry="fetchData()">
      <el-alert v-if="error" type="warning" :closable="false" show-icon :title="$t('legacy.x1e823103')"/>
      <el-table :data="items" stripe><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="campaign_name" :label="$t('legacy.x36c6f572')" min-width="150"/><el-table-column prop="campaign_type" :label="$t('legacy.x226b0912')" width="90"/><el-table-column label="SMPP" width="170"><template #default="{row}"><span v-if="row.smpp_config_id">{{ smppName(row.smpp_config_id) }}</span><span v-else class="muted">{{ $t('legacy.x18c63459') }}</span></template></el-table-column><el-table-column prop="msisdn" :label="$t('smsLog.msisdn')" width="150"/><el-table-column prop="language" :label="$t('common.language')" width="80"/><el-table-column prop="content" :label="$t('legacy.x2d711b09')" min-width="220" show-overflow-tooltip/><el-table-column :label="$t('common.status')" width="110"><template #default="{row}"><StatusTag :status="row.status"/></template></el-table-column><el-table-column prop="attempts" :label="$t('legacy.xfa8f026e')" width="70"/><el-table-column prop="error_msg" :label="$t('legacy.x7030ff64')" min-width="160" show-overflow-tooltip/><el-table-column prop="updated_at" :label="$t('common.updated_at')" width="180"/><el-table-column :label="$t('common.action')" width="90" fixed="right"><template #default="{row}"><el-dropdown v-if="['submitted','accepted','failed','expired'].includes(row.status)" trigger="click" @command="(cmd:any)=>onAction(cmd,row)"><el-button link type="primary">{{ $t('common.more') }}<el-icon><ArrowDown/></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="retry">{{ $t('legacy.xe3095030') }}</el-dropdown-item><el-dropdown-item v-if="['submitted','accepted'].includes(row.status)" command="confirm-delivered">{{ $t('legacy.xc28d5575') }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown><span v-else class="muted">—</span></template></el-table-column></el-table>
      <el-pagination v-model:current-page="page" :page-size="pageSize" :page-sizes="[20,50,100]" :total="total" layout="total, sizes, prev, pager, next" class="pagination" @current-change="changePage" @size-change="changePageSize"/>
    </DataState></div>
    <el-dialog v-model="exclusionVisible" :title="$t('legacy.x491edbaf')" width="620px"><el-form inline><el-form-item :label="$t('smsLog.msisdn')"><el-input v-model="exclusionForm.msisdn"/></el-form-item><el-form-item :label="$t('legacy.x41dfb0bf')"><el-input v-model="exclusionForm.reason"/></el-form-item><el-button type="primary" @click="createExclusion">{{ $t('legacy.xb58c7549') }}</el-button></el-form><el-table :data="exclusions" max-height="360"><el-table-column prop="msisdn" :label="$t('smsLog.msisdn')"/><el-table-column prop="reason" :label="$t('legacy.x41dfb0bf')"/><el-table-column prop="created_at" :label="$t('common.created_at')" width="180"/><el-table-column :label="$t('common.action')" width="80"><template #default="{row}"><el-button link type="danger" @click="removeExclusion(row.id)">{{ $t('common.delete') }}</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="exclusionPage" :page-size="exclusionPageSize" :total="exclusionTotal" layout="total, prev, pager, next" class="pagination" @current-change="changeExclusionPage"/></el-dialog>
  </div>
</template>
<script setup lang="ts">
import i18n from '@/i18n'
import { computed,onBeforeUnmount,onMounted,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import StatusTag from '@/components/StatusTag.vue';import PageHeader from '@/components/PageHeader.vue';import DataState from '@/components/DataState.vue';import PollingStatus from '@/components/PollingStatus.vue'
import {addExclusion,confirmDelivered,deleteExclusion,getExclusions,getSmsTasks,getSmsTaskStats,retrySmsTask} from '@/api/smsTasks'
import {getSmppConfigs} from '@/api/smpp'
withDefaults(defineProps<{ embedded?: boolean }>(), { embedded: false })
const PAGE_SIZE_KEY='mc.sms-tasks.page-size',route=useRoute(),router=useRouter(),items=ref<any[]>([]),stats=ref<Record<string,number>>({}),loading=ref(false),error=ref(''),total=ref(0),page=ref(Math.max(1,Number(route.query.page)||1)),pageSize=ref(Number(localStorage.getItem(PAGE_SIZE_KEY))||50),status=ref(typeof route.query.status==='string'?route.query.status:''),campaignType=ref(typeof route.query.type==='string'?route.query.type:''),smppFilter=ref(typeof route.query.smpp==='string'&&Number.isFinite(Number(route.query.smpp))?Number(route.query.smpp):-1),smppConfigs=ref<any[]>([]),autoRefresh=ref(true),lastUpdated=ref<Date|null>(null),pollState=ref<'live'|'stale'|'offline'>('stale'),exclusionVisible=ref(false),exclusions=ref<any[]>([]),exclusionForm=ref({msisdn:'',reason:''}),exclusionPage=ref(1),exclusionPageSize=ref(50),exclusionTotal=ref(0)
const statuses=['queued','sending','submitted','accepted','delivered','retrying','failed','expired'],statItems=computed(()=>[{key:'total',label:i18n.global.t('legacy.x0f7991c2')},{key:'queued',label:i18n.global.t('legacy.xe5ac1d20')},{key:'submitted',label:i18n.global.t('legacy.xf5e626da')},{key:'delivered',label:i18n.global.t('legacy.xf87f48f2')},{key:'retrying',label:i18n.global.t('legacy.xd7a2a293')},{key:'failed',label:i18n.global.t('common.fail')}]);let timer=0,inFlight=false
function smppName(configId:number){const cfg=smppConfigs.value.find((c:any)=>c.id===configId);return cfg?`${cfg.name} (${cfg.host}:${cfg.port})`:`#${configId}`}
function syncUrl(){router.replace({query:{...route.query,status:status.value||undefined,type:campaignType.value||undefined,smpp:smppFilter.value>=0?String(smppFilter.value):undefined,page:page.value>1?String(page.value):undefined}})}
async function fetchData(silent=false){if(inFlight)return;inFlight=true;if(!silent)loading.value=true;try{const [tasks,summary]=await Promise.all([getSmsTasks({page:page.value,page_size:pageSize.value,status:status.value||undefined,campaign_type:campaignType.value||undefined,smpp_config_id:smppFilter.value>=0?smppFilter.value:undefined}),getSmsTaskStats()]);items.value=tasks.data.items;total.value=tasks.data.total;stats.value=summary.data;lastUpdated.value=new Date();pollState.value='live';error.value=''}catch(e:any){error.value=e.response?.data?.detail||i18n.global.t('common.connectionFailed');pollState.value=lastUpdated.value?'stale':'offline'}finally{inFlight=false;loading.value=false}}
function applyFilters(){page.value=1;syncUrl();fetchData()} function changePage(){syncUrl();fetchData()} function changePageSize(size:number){pageSize.value=size;localStorage.setItem(PAGE_SIZE_KEY,String(size));page.value=1;syncUrl();fetchData()}
async function onAction(cmd:string,row:any){try{if(cmd==='retry'){await retrySmsTask(row.id);ElMessage.success(i18n.global.t('legacy.x324dd993'))}else if(cmd==='confirm-delivered'){await confirmDelivered(row.id);ElMessage.success(i18n.global.t('legacy.x093c631e'))}fetchData()}catch(e:any){ElMessage.error(e.response?.data?.detail||i18n.global.t('legacy.xfb5dedea'))}}
async function openExclusions(){exclusionVisible.value=true;const res=await getExclusions({page:exclusionPage.value,page_size:exclusionPageSize.value});exclusions.value=res.data.items||[];exclusionTotal.value=res.data.total??exclusions.value.length} async function createExclusion(){if(!exclusionForm.value.msisdn)return ElMessage.warning(i18n.global.t('legacy.x6e4f4b33'));await addExclusion(exclusionForm.value.msisdn,exclusionForm.value.reason);exclusionForm.value={msisdn:'',reason:''};await openExclusions()} async function removeExclusion(id:number){await deleteExclusion(id);await openExclusions()} function changeExclusionPage(nextPage:number){exclusionPage.value=nextPage;void openExclusions()}
watch(autoRefresh,value=>{pollState.value=value?(lastUpdated.value?'live':'stale'):'stale'})
onMounted(()=>{getSmppConfigs().then((res:any)=>{smppConfigs.value=res.data}).catch(()=>{});fetchData();timer=window.setInterval(()=>{if(autoRefresh.value&&!document.hidden)fetchData(true)},30000)});onBeforeUnmount(()=>window.clearInterval(timer))
</script>
<style scoped>.embedded-header{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:16px}.embedded-header h3{margin:0;color:var(--mc-text);font-size:16px}.embedded-header p{margin:5px 0 0;color:var(--mc-text-secondary);font-size:12px}.embedded-actions{display:flex;flex-wrap:wrap;align-items:center;justify-content:flex-end;gap:8px}.stats,.filters{margin-bottom:16px}.filter-bar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.filter-bar .el-form{flex:1;min-width:0}.stats .el-col{margin-bottom:12px}.stat-label{color:var(--mc-text-secondary);font-size:13px}.stat-value{margin-top:8px;font-size:26px;font-weight:600}.pagination{justify-content:flex-end;padding:16px}.muted{color:var(--mc-text-tertiary)}@media(max-width:767px){.embedded-header{flex-direction:column;gap:10px}.embedded-actions{width:100%;justify-content:flex-start}:deep(.page-actions){align-items:center}.filters :deep(.el-form-item){width:100%;margin-right:0}.filters :deep(.el-select){width:100%!important}}</style>
